const state={user:null,public:null,view:'dashboard',channels:[],models:[],users:[],logs:[],keys:[],announcements:[]};
const FORMAT_LABELS={chat:'OpenAI Chat Completions',responses:'OpenAI Responses',anthropic:'Anthropic Messages',image:'OpenAI Images',tts:'OpenAI TTS',transcription:'OpenAI Audio 语音识别'};
const KIND_LABELS={language:'语言',image:'图像生成',tts:'语音合成',transcription:'语音识别',unclassified:'待确认类型'};
const copy=(key,fallback)=>(state.public?.copy||{})[key]||fallback;
const $=s=>document.querySelector(s); const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(text){const d=document.createElement('div');d.textContent=text;$('#toast').append(d);setTimeout(()=>d.remove(),4500)}
async function api(path,method='GET',data){let opts={method,credentials:'same-origin',headers:{}};if(data!==undefined){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(data)}const r=await fetch(path,opts);let d;try{d=await r.json()}catch{d={}}if(!r.ok)throw new Error(d.detail||d.error?.message||`请求失败 ${r.status}`);return d}
const LANGUAGE_CAPABILITY_OPTIONS=[['reasoning','推理'],['vision','视觉'],['image_input','图片输入'],['tools','工具调用']];
function capabilityOn(caps,key){const value=caps?.[key];return value===undefined||(value&&typeof value==='object'&&typeof value.supported==='boolean'?value.supported:value!==false)}
function supportedCaps(caps,kind){return kind==='language'?LANGUAGE_CAPABILITY_OPTIONS.filter(([key])=>capabilityOn(caps,key)).map(([,label])=>label).join(' · ')||'未启用':'—'}
function capabilitySummary(caps,kind){if(kind!=='language')return '<span class="small">—</span>';const labels=LANGUAGE_CAPABILITY_OPTIONS.filter(([key])=>capabilityOn(caps,key)).map(([,label])=>label);return labels.length?`<div class="capability-tags">${labels.map(label=>badge(label,'pink')).join('')}</div>`:'<span class="small">未启用</span>'}
function money(v){return Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:6})}
const hasPrice=v=>v!==null&&v!==undefined&&v!=='';
function isFreeModel(m){return m.billing_mode==='request'?!Number(m.unit_price):![m.input_price,m.output_price,m.cache_read_price,m.cache_write_price].some(v=>hasPrice(v)&&Number(v))}
function priceText(m){if(isFreeModel(m))return '免费';if(m.billing_mode==='request')return `按次 ${money(m.unit_price)} / 次`;if(m.kind==='tts')return `按量 ${money(m.input_price)} / 百万字符`;let parts=[`输入 ${money(m.input_price)}`,`输出 ${money(m.output_price)}`];if(m.kind==='language'){if(hasPrice(m.cache_read_price))parts.push(`缓存读取 ${money(m.cache_read_price)}`);if(hasPrice(m.cache_write_price))parts.push(`缓存写入 ${money(m.cache_write_price)}`)}return `按量 ${parts.join(' · ')} / 百万 token`}
function usageText(l){if(!l.input_tokens&&!l.output_tokens)return '—';let cache=[l.cache_read_tokens?`缓存读 ${l.cache_read_tokens}`:'',l.cache_write_tokens?`缓存写 ${l.cache_write_tokens}`:''].filter(Boolean).join(' · ');return `入 ${l.input_tokens||0} / 出 ${l.output_tokens||0}${cache?`<br>${cache}`:''}`}
function date(t){return t?new Date(t*1000).toLocaleString('zh-CN'):'—'}
function badge(text,tone=''){return `<span class="badge ${tone}">${esc(text)}</span>`}
function formatName(format){return FORMAT_LABELS[format]||format}
function kindName(kind){return KIND_LABELS[kind]||kind}
function channelSupports(channel,kind){if(channel.format==='anthropic')return kind==='language';if(['image','tts','transcription'].includes(channel.format))return channel.format===kind;return ['chat','responses'].includes(channel.format)&&kind==='language'}
function empty(text='暂无数据。'){return `<div class="empty"><div class="flower">✿</div>${esc(text)}</div>`}
function panel(title,desc,actions,body){return `<div class="panel"><div class="panel-head"><div><h3>${title}</h3>${desc?`<p>${desc}</p>`:''}</div><div class="actions">${actions||''}</div></div>${body}</div>`}
function table(headers,rows){return rows.length?`<div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty()}
function modal(title,html,wide=false){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal .modal').classList.toggle('modal-wide',wide);$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden');$('#modal-body').innerHTML=''}
function field(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function textarea(label,name,value='',rows=3){return `<label>${label}<textarea name="${name}" rows="${rows}">${esc(value)}</textarea></label>`}
function select(label,name,options,value){return `<label>${label}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v==value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
function formData(form){return Object.fromEntries(new FormData(form).entries())}
function control(form,name){return form.elements.namedItem(name)}
const I={home:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 11l9-8 9 8"/><path d="M5 10v10h14V10"/></svg>',doc:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/></svg>',spark:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3l2 6 6 3-6 3-2 6-2-6-6-3 6-3z"/></svg>',key:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="8" cy="15" r="4"/><path d="M11 12l9-9M16 7l3 3"/></svg>',heart:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 20s-8-5-8-11a4.5 4.5 0 0 1 8-2.5A4.5 4.5 0 0 1 20 9c0 6-8 11-8 11z"/></svg>',clock:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>',user:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 4-6 8-6s8 2 8 6"/></svg>',layers:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3l9 5-9 5-9-5z"/><path d="M3 13l9 5 9-5"/></svg>',grid:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="4" y="4" width="7" height="7" rx="1"/><rect x="13" y="4" width="7" height="7" rx="1"/><rect x="4" y="13" width="7" height="7" rx="1"/><rect x="13" y="13" width="7" height="7" rx="1"/></svg>',users:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="9" cy="8" r="3.5"/><path d="M2 20c0-4 3-6 7-6s7 2 7 6"/><path d="M16 4.5a3.5 3.5 0 0 1 0 7M18 14c3 .7 4 3 4 6"/></svg>',gift:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="8" width="18" height="4" rx="1"/><path d="M5 12v9h14v-9M12 8v13M12 8c-3 0-5-1-5-3s3-2 5 3c2-5 5-5 5-3s-2 3-5 3"/></svg>',sliders:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 7h10M18 7h2M4 17h2M10 17h10"/><circle cx="16" cy="7" r="2"/><circle cx="8" cy="17" r="2"/></svg>',logout:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 4H5v16h4"/><path d="M16 8l4 4-4 4M20 12H9"/></svg>'};
const menu=[['dashboard',I.home,'总览'],['announcements',I.doc,'公告'],['my-models',I.spark,'可用模型'],['keys',I.key,'我的密钥'],['redeem',I.heart,'兑换喵币'],['logs',I.clock,'请求日志'],['account',I.user,'账户设置']];
const adminMenu=[['channels',I.layers,'上游渠道'],['models',I.grid,'下游模型'],['users',I.users,'用户管理'],['codes',I.gift,'兑换码'],['settings',I.sliders,'站点设置']];
function nav(){let html='<div class="nav-caption">用户中心</div>'+menu.map(([id,ic,name])=>`<button class="nav-item ${state.view===id?'active':''}" data-view="${id}"><span class="ico">${ic}</span>${id==='redeem'?'兑换'+state.public.currency_name:name}</button>`).join('');if(state.user?.is_admin)html+='<div class="nav-caption">管理后台</div>'+adminMenu.map(([id,ic,name])=>`<button class="nav-item ${state.view===id?'active':''}" data-view="${id}"><span class="ico">${ic}</span>${name}</button>`).join('');$('#nav').innerHTML=html;$('#side-user').textContent=state.user.username;$('#side-role').textContent=state.user.is_admin?'管理员':'普通用户';$('#balance-pill').textContent=state.user.unlimited_balance?`∞ ${state.public.currency_name}`:`${money(state.user.balance)} ${state.public.currency_name}`}
async function loadView(view){state.view=view;nav();$('#page-title').textContent=view==='redeem'?'兑换'+state.public.currency_name:([...menu,...adminMenu].find(x=>x[0]===view)?.[2]||view);$('#content').innerHTML='<div class="panel">加载中…</div>';$('.sidebar').classList.remove('open');try{await ({dashboard,announcements,'my-models':myModels,keys,redeem,account,channels,models,users,codes,logs,settings})[view]()}catch(e){$('#content').innerHTML=panel('加载失败','',`<button class="secondary" data-view="${view}">重试</button>`,esc(e.message))}}
async function dashboard(){const [models,keys]=await Promise.all([api('/api/me/models'),api('/api/me/keys?summary=true')]);state.keys=keys;let content=`<div class="hero"><p class="eyebrow">模型服务概览</p><h3>${esc(state.public.welcome_text)}</h3><p>${esc(copy('dashboard_intro','集中查看已授权模型、管理 API 密钥并了解账户用量。'))}</p></div><div class="cards"><div class="card"><span class="icon">${I.spark}</span><div class="label">可用模型</div><div class="value">${models.length}</div></div><div class="card"><span class="icon">${I.key}</span><div class="label">我的密钥</div><div class="value">${keys.length}</div></div><div class="card"><span class="icon">${I.heart}</span><div class="label">${esc(state.public.currency_name)}余额</div><div class="value">${state.user.unlimited_balance?'∞':money(state.user.balance)}</div></div></div>`;
content+=panel('最新公告','站点发布的最新消息。',`<button class="secondary" data-view="announcements">查看全部</button>`,`<div id="dashboard-announcements" class="announcement-list"><div class="small">加载中…</div></div>`);
content+=panel(esc(copy('dashboard_api_title','API 接入')),esc(copy('dashboard_api_hint','通过统一接口调用您已获授权的模型。')),`<button class="secondary" data-copy="${location.origin}">复制地址</button>`,`<div class="muted-block"><strong>API 地址</strong><div class="code" style="margin-top:8px">${esc(location.origin)}/v1</div><p class="small" style="margin:10px 0 0">${esc(copy('dashboard_api_help','兼容 OpenAI Chat Completions、Responses、Anthropic Messages，以及图像生成和语音接口。'))}</p></div>`);
content+=panel('最近创建的密钥','密钥可在“我的密钥”中再次查看和复制。',`<button class="primary" data-action="new-key">创建密钥</button>`,keys.length?table(['名称','前缀','创建时间'],keys.slice(0,3).map(k=>`<tr><td>${esc(k.name)}</td><td><span class="code">${esc(k.prefix)}…</span></td><td>${date(k.created_at)}</td></tr>`)):empty('暂无 API 密钥。请创建密钥以开始调用。'));$('#content').innerHTML=content;api('/api/announcements').then(items=>{state.announcements=items;$('#dashboard-announcements').innerHTML=items.length?items.slice(0,2).map(announcementCard).join(''):empty('暂无公告。')}).catch(()=>{$('#dashboard-announcements').innerHTML=empty('公告加载失败。')});if(state.public.hero_image){const hero=$('.hero');hero.classList.add('has-image');hero.style.backgroundImage=`url(${state.public.hero_image})`}}
async function myModels(){let data=await api('/api/me/models');$('#content').innerHTML=panel('你的模型列表','只展示管理员分配给你的模型。',`<button class="secondary" data-copy="${location.origin}/v1/models">复制模型接口</button>`,table(['模型 ID','类型','能力','价格'],data.map(m=>`<tr><td><span class="code">${esc(m.public_id)}</span></td><td>${badge(({language:'语言',tts:'语音合成',transcription:'语音识别',image:'绘图'})[m.kind]||m.kind,'pink')}</td><td>${esc(supportedCaps(m.capabilities,m.kind))}</td><td class="small">${esc(priceText(m))}</td></tr>`)))}
async function redeem(){let curr=esc(state.public.currency_name);$('#content').innerHTML=panel(`兑换${curr}`,'输入管理员给你的兑换码。','',`<form id="redeem-form" style="max-width:420px">${field('兑换码','code','','text','required placeholder="XF-XXXXXXXX-XXXXXXXX"')}<button class="primary">立即兑换</button></form>`);$('#redeem-form').onsubmit=async e=>{e.preventDefault();try{let d=await api('/api/me/redeem','POST',{code:e.target.elements.namedItem("code").value});toast(`兑换成功：${money(d.amount)} ${state.public.currency_name}`);e.target.reset();await refreshMe()}catch(x){toast(x.message)}}}
async function account(){$('#content').innerHTML=panel('账户设置','更新登录密码。','',`<form id="password-form" style="max-width:430px">${field('当前密码','old_password','','password','required autocomplete="current-password"')}${field('新密码','new_password','','password','required autocomplete="new-password"')}<button class="primary">修改密码</button></form>`);$('#password-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/me/password','POST',formData(e.target));e.target.reset();toast('密码已更新')}catch(x){toast(x.message)}}}
async function channels(){state.channels=await api('/api/admin/channels');$('#content').innerHTML=panel('上游渠道','可添加 Chat、Responses、Anthropic，以及 OpenAI 图像和语音渠道。',`<button class="primary" data-action="new-channel">＋ 添加渠道</button>`,table(['名称','接口格式','地址','状态','操作'],state.channels.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${badge(formatName(c.format),'pink')}</td><td class="small">${esc(c.base_url)}${c.use_proxy?`<br>${badge('代理 '+(c.proxy_url||'http://127.0.0.1:7890'))}`:''}</td><td>${badge(c.enabled?'启用':'停用',c.enabled?'green':'orange')}</td><td><button class="text-btn" data-action="up-models" data-id="${c.id}">模型</button><button class="text-btn" data-action="edit-channel" data-id="${c.id}">编辑</button><button class="text-btn" data-action="delete-channel" data-id="${c.id}">删除</button></td></tr>`)))}
function channelForm(c={}){modal(c.id?'编辑渠道':'添加渠道',`<form id="channel-form"><div class="form-grid">${field('渠道名称','name',c.name||'','text','required')}${select('接口格式','format',[['chat','OpenAI Chat Completions'],['responses','OpenAI Responses'],['anthropic','Anthropic Messages'],['image','OpenAI Images（图像）'],['tts','OpenAI TTS（语音合成）'],['transcription','OpenAI Audio（语音识别）']],c.format||'chat')}<div class="full"><p class="small">Chat、Responses、Anthropic 渠道只承载语言模型；图像、语音合成、语音识别模型请使用对应的专用渠道。</p></div><div class="full">${field('上游 API 地址','base_url',c.base_url||'','url','required placeholder="https://api.example.com"')}<p class="small channel-url-hint">填写上游 API 根地址。末尾带不带 /v1 都可以，网关会自动拼接接口路径；不要填写 /chat/completions 等完整接口地址。</p></div><div class="full">${field(c.id?'上游 API Key（留空保持原值）':'上游 API Key','api_key','','password',c.id?'':'required')}</div><div class="full">${textarea('额外请求头（JSON 对象）','extra_headers',JSON.stringify(c.extra_headers||{},null,2),3)}</div><div class="full"><label class="toggle"><input type="checkbox" name="use_proxy" ${c.use_proxy?'checked':''}> 通过本地 HTTP 代理连接上游</label><div class="proxy-field ${c.use_proxy?'':'hidden'}">${field('代理地址','proxy_url',c.proxy_url||'http://127.0.0.1:7890','text','placeholder="http://127.0.0.1:7890"')}<p class="small">请求上游接口和拉取模型列表都会经过此代理。</p></div></div><label class="toggle"><input type="checkbox" name="enabled" ${c.enabled!==false&&c.enabled!==0?'checked':''}> 启用此渠道</label></div><div class="actions"><button type="button" class="secondary" data-close>取消</button><button class="primary">保存</button></div></form>`);const proxyBox=control($('#channel-form'),'use_proxy');proxyBox.onchange=()=>$('#channel-form .proxy-field').classList.toggle('hidden',!proxyBox.checked);$('#channel-form').onsubmit=async e=>{e.preventDefault();let f=formData(e.target);try{let extra=JSON.parse(f.extra_headers||'{}');let data={name:f.name,format:f.format,base_url:f.base_url,api_key:f.api_key,extra_headers:extra,enabled:control(e.target,'enabled').checked,use_proxy:control(e.target,'use_proxy').checked,proxy_url:(f.proxy_url||'').trim()};await api('/api/admin/channels'+(c.id?'/'+c.id:''),c.id?'PUT':'POST',data);closeModal();toast('渠道已保存');await channels()}catch(x){toast(x.message)}}}
async function upModels(id){
  const channel=state.channels.find(x=>x.id==id),title=`${channel.name} · 上游模型`,actions=`<div class="actions" style="margin-bottom:14px"><button class="primary" data-action="fetch-models" data-id="${id}">↻ 一键拉取</button><button class="secondary" data-action="custom-up-model" data-id="${id}">＋ 自定义模型</button><button class="secondary" data-action="import-all" data-id="${id}">全部导入下游</button></div>`;
  const ticket=state.upModelsTicket=(state.upModelsTicket||0)+1,open=()=>$('#modal-title').textContent===title&&!$('#modal').classList.contains('hidden');
  if(!open())modal(title,actions+'<div class="empty">加载中…</div>',true);
  let data;try{data=await api(`/api/admin/channels/${id}/models`)}catch(x){if(ticket===state.upModelsTicket&&open())$('#modal-body').innerHTML=actions+empty(x.message);throw x}
  if(ticket!==state.upModelsTicket||!open())return;state.upModelList={id,data};
  const rows=data.map(m=>`<tr><td class="code">${esc(m.model_id)}</td><td>${esc(kindName(m.kind))}</td><td>${capabilitySummary(m.capabilities,m.kind)}</td><td class="up-model-actions"><button class="text-btn" data-action="edit-up-model" data-id="${id}" data-model="${esc(m.model_id)}">编辑类型与能力</button><button class="text-btn" data-action="import-one" data-id="${id}" data-model="${esc(m.model_id)}">导入</button></td></tr>`);
  $('#modal-body').innerHTML=actions+table(['模型 ID','类型','能力','操作'],rows);
}
async function quickImport(){state.channels=await api('/api/admin/channels');modal('一键导入上游模型',`<p class="small">将渠道的上游模型创建为同名下游模型，并自动添加路由。</p><form id="import-form">${select('选择渠道','channel_id',state.channels.map(c=>[c.id,c.name]),state.channels[0]?.id)}<div class="actions"><button type="button" class="secondary" data-close>取消</button><button class="primary">全部导入</button></div></form>`);$('#import-form').onsubmit=async e=>{e.preventDefault();try{let d=await api('/api/admin/models/import','POST',{channel_id:Number(control(e.target,'channel_id').value)});closeModal();toast(`已处理 ${d.count} 个模型`);await models()}catch(x){toast(x.message)}}}
function assetField(label,name,url){return `<div class="asset-row"><strong>${label}</strong><input type="file" accept="image/png,image/jpeg,image/webp,image/gif" data-upload="${name}"><input name="${name}" type="hidden" value="${esc(url||'')}"><div class="asset-preview">${url?`<img class="asset-thumb" alt="${label}" src="${esc(url)}">`:'<span class="small">尚未上传</span>'}</div><button type="button" class="text-btn" data-clear-asset="${name}">清除</button></div>`}
async function settings(){let d=await api('/api/admin/settings'),t=d.theme||{},c=d.copy||{};let colors=[['accent','主色'],['accent_dark','主色深色'],['background','页面背景'],['ink','正文颜色'],['muted','辅助文字']];let assetHtml=[['site_logo','站点标志'],['login_image','登录页插画'],['hero_image','首页横幅图片'],['favicon','浏览器图标']].map(([k,l])=>assetField(l,k,d[k])).join('');let copyHtml=[['login_art','登录插画文案'],['login_button','登录按钮'],['register_button','注册按钮'],['dashboard_intro','首页介绍'],['dashboard_api_title','接入卡片标题'],['dashboard_api_hint','接入卡片副标题'],['dashboard_api_help','接入说明']].map(([k,l])=>field(l,'copy_'+k,c[k]||'')).join('');$('#content').innerHTML=panel('站点与路由设置','图片、配色、字体、文案、样式与重试策略均可调整。','',`<form id="settings-form"><div class="setting-section"><h4>站点文案</h4><div class="form-grid">${field('站点名称','site_name',d.site_name)}${field('货币名称','currency_name',d.currency_name)}<div class="full">${field('副标题','tagline',d.tagline)}</div><div class="full">${field('欢迎语','welcome_text',d.welcome_text)}</div><div class="full">${field('页脚','footer_text',d.footer_text)}</div>${copyHtml}<label class="toggle"><input type="checkbox" name="registration_open" ${d.registration_open?'checked':''}> 开放用户注册</label></div></div><div class="setting-section"><h4>全站文字替换</h4><p class="small">用 JSON 对象指定“原文案”:“新文案”，可覆盖页面中的多数按钮、标题和提示。</p>${textarea('文字替换表（JSON）','text_overrides',JSON.stringify(d.text_overrides||{},null,2),8)}</div><div class="setting-section"><h4>图片素材</h4><p class="small">支持 PNG、JPG、WebP、GIF，每张不超过 5 MB。上传后点击页面底部“保存设置”。</p>${assetHtml}<label class="hero-fade-label">横幅图片遮罩浓度：<output id="hero-fade-value">${Math.round((d.hero_overlay_opacity??.22)*100)}%</output><input type="range" name="hero_overlay_opacity" min="0" max="1" step="0.01" value="${d.hero_overlay_opacity??.22}"></label><p class="small">数值越低，图片越鲜明；左侧文字区域保留柔和遮罩。</p></div><div class="setting-section"><h4>颜色与字体</h4><div class="form-grid">${colors.map(([k,l])=>`<label>${l}<div class="color-field"><input type="color" data-color="${k}" value="${esc(t[k]||'#ffffff')}"><input name="theme_${k}" type="text" value="${esc(t[k]||'')}"></div></label>`).join('')}<div class="full">${field('字体 CSS font-family','theme_font',t.font||'')}</div></div></div><div class="setting-section"><h4>自定义 CSS</h4><p class="small">可覆盖整个站点的布局、字体、边距和组件外观。</p>${textarea('自定义样式','custom_css',d.custom_css||'',10)}</div><div class="setting-section"><h4>失败切换</h4><div class="form-grid">${field('需要重试的 HTTP 状态码（逗号分隔）','retry_statuses',d.retry_statuses.join(', '))}${field('每条路由最多尝试次数','max_attempts_per_route',d.max_attempts_per_route,'number','min="1" max="3"')}<div class="full">${textarea('需要重试的错误文本（每行一条）','retry_text',d.retry_text.join('\n'))}</div>${field('连接超时（秒）','connect_timeout',d.connect_timeout,'number','min="1"')}${field('首 token 超时（秒）','first_token_timeout',d.first_token_timeout,'number','min="1"')}${field('流空闲超时（秒）','idle_timeout',d.idle_timeout,'number','min="1"')}${field('总超时（秒）','total_timeout',d.total_timeout,'number','min="1"')}</div></div><div class="actions"><button class="primary">保存设置</button></div></form>`);let form=$('#settings-form');control(form,'hero_overlay_opacity').oninput=()=>$('#hero-fade-value').textContent=Math.round(Number(control(form,'hero_overlay_opacity').value)*100)+'%';form.querySelectorAll('[data-upload]').forEach(inp=>inp.onchange=async()=>{let file=inp.files[0];if(!file)return;let fd=new FormData();fd.append('file',file);try{let r=await fetch('/api/admin/assets',{method:'POST',body:fd,credentials:'same-origin'});let x=await r.json();if(!r.ok)throw new Error(x.detail||'上传失败');form.elements.namedItem(inp.dataset.upload).value=x.url;let slot=inp.closest('.asset-row').querySelector('.asset-preview'),preview=document.createElement('img');preview.className='asset-thumb';preview.alt=inp.closest('.asset-row').querySelector('strong').textContent;preview.src=x.url;slot.replaceChildren(preview);toast('图片已上传，保存设置后生效')}catch(e){inp.value='';toast(e.message)}});form.querySelectorAll('[data-color]').forEach(inp=>inp.oninput=()=>form.elements.namedItem('theme_'+inp.dataset.color).value=inp.value);form.querySelectorAll('[data-clear-asset]').forEach(btn=>btn.onclick=()=>{let row=btn.closest('.asset-row');form.elements.namedItem(btn.dataset.clearAsset).value='';row.querySelector('[data-upload]').value='';row.querySelector('.asset-preview').innerHTML='<span class="small">尚未上传</span>'});form.onsubmit=async e=>{e.preventDefault();let f=formData(form);for(let k of ['connect_timeout','first_token_timeout','idle_timeout','total_timeout','max_attempts_per_route','hero_overlay_opacity'])f[k]=Number(f[k]);f.retry_statuses=f.retry_statuses.split(/[,，\s]+/).filter(Boolean).map(Number);f.retry_text=f.retry_text.split('\n').map(x=>x.trim()).filter(Boolean);f.registration_open=control(form,'registration_open').checked;try{f.text_overrides=JSON.parse(f.text_overrides||'{}')}catch{toast('文字替换表不是有效 JSON');return}f.theme={};for(let k of [...colors.map(x=>x[0]),'font']){f.theme[k]=f['theme_'+k];delete f['theme_'+k]}f.copy={};for(let k of ['login_art','login_button','register_button','dashboard_intro','dashboard_api_title','dashboard_api_hint','dashboard_api_help']){f.copy[k]=f['copy_'+k];delete f['copy_'+k]}try{await api('/api/admin/settings','PUT',f);toast('设置已保存');state.public=await api('/api/public');applyPublic();await settings()}catch(x){toast(x.message)}}}
function applyPublic(){document.title=state.public.site_name;$('#login-title').textContent=state.public.site_name;$('#login-tagline').textContent=state.public.tagline;$('#side-name').textContent=state.public.site_name;$('#footer').textContent=state.public.footer_text;$('#art-caption').textContent=copy('login_art','统一管理模型服务，安全、高效地接入 API。');$('#register-switch').style.display=state.public.registration_open?'':'none';$('#register-hint').textContent=state.public.registration_open?'注册已开放，您可以创建账户。':'注册暂未开放，请联系管理员。';$('#favicon').href=state.public.favicon||'data:,';let img=$('#login-art-image');img.classList.toggle('hidden',!state.public.login_image);$('.auth-art').classList.toggle('has-image',!!state.public.login_image);if(state.public.login_image)img.src=state.public.login_image;document.querySelectorAll('.brandmark').forEach(el=>{el.classList.toggle('has-logo',!!state.public.site_logo);el.innerHTML=state.public.site_logo?`<img alt="站点标志" src="${esc(state.public.site_logo)}">`:'✿'});let t=state.public.theme||{};let vars={accent:'--pink',accent_dark:'--pink-dark',background:'--page-bg',ink:'--ink',muted:'--muted',font:'--site-font'};for(let [k,v] of Object.entries(vars))if(t[k])document.documentElement.style.setProperty(v,t[k]);document.documentElement.style.setProperty('--hero-image-fade',String(state.public.hero_overlay_opacity??.22));$('#custom-css').textContent=state.public.custom_css||'';let on=$('#register-switch').classList.contains('selected');$('#auth-form button[type=submit]').innerHTML=esc(copy(on?'register_button':'login_button',on?'注册账号':'登录'))+' <span>↗</span>'}
async function refreshMe(){state.user=await api('/api/me');nav()}
async function boot(){state.public=await api('/api/public');applyPublic();try{await refreshMe();$('#auth').classList.add('hidden');$('#shell').classList.remove('hidden');await loadView(state.view)}catch{$('#auth').classList.remove('hidden');$('#shell').classList.add('hidden')}}
$('#auth-form').onsubmit=async e=>{e.preventDefault();let d=formData(e.target);try{await api($('#register-switch').classList.contains('selected')?'/api/register':'/api/login','POST',d);if($('#register-switch').classList.contains('selected')){toast('注册成功，请登录');$('#login-switch').click()}else await boot()}catch(x){toast(x.message)}};
for(const [id,on] of [['login-switch',false],['register-switch',true]])$('#'+id).onclick=()=>{if(on&&!state.public.registration_open)return;$('#login-switch').classList.toggle('selected',!on);$('#register-switch').classList.toggle('selected',on);$('#auth-form button[type=submit]').innerHTML=esc(copy(on?'register_button':'login_button',on?'注册账号':'登录'))+' <span>↗</span>'};
$('#logout').onclick=async()=>{await api('/api/logout','POST');state.user=null;await boot()};$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');document.addEventListener('click',e=>{const sb=$('.sidebar');if(sb&&sb.classList.contains('open')&&!sb.contains(e.target)&&!e.target.closest('#menu'))sb.classList.remove('open')});$('#modal-close').onclick=closeModal;$('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};
document.addEventListener('click',async e=>{let el=e.target.closest('[data-view],[data-close],[data-copy],[data-action]');if(!el)return;if(el.dataset.view){loadView(el.dataset.view);return}if(el.hasAttribute('data-close')){closeModal();return}if(el.dataset.copy){try{await navigator.clipboard.writeText(el.dataset.copy);toast('已复制')}catch{toast('复制失败，请手动复制')}return}let a=el.dataset.action,id=Number(el.dataset.id);try{if(a==='new-key')await newKey();if(a==='edit-key')await keyForm(state.keys.find(x=>x.id===id));if(a==='delete-key'&&confirm('确定删除这把密钥？')){await api(`/api/me/keys/${id}`,'DELETE');await keys()}if(a==='new-channel')channelForm();if(a==='edit-channel')channelForm(state.channels.find(x=>x.id===id));if(a==='delete-channel'&&confirm('删除渠道也会删除它的所有路由，确定吗？')){await api(`/api/admin/channels/${id}`,'DELETE');await channels()}if(a==='up-models')await upModels(id);if(a==='fetch-models'){el.disabled=true;el.innerHTML='<span class="spinner"></span> 拉取中';let d=await api(`/api/admin/channels/${id}/fetch-models`,'POST');toast(`已拉取 ${d.count} 个模型`);await upModels(id)}if(a==='custom-up-model')customUpModel(id);if(a==='edit-up-model'){let data=state.upModelList?.id===id?state.upModelList.data:await api(`/api/admin/channels/${id}/models`);customUpModel(id,data.find(x=>x.model_id===el.dataset.model))};if(a==='import-one'||a==='import-all'){let d=await api('/api/admin/models/import','POST',{channel_id:id,model_ids:a==='import-one'?[el.dataset.model]:[]});toast(`已处理 ${d.count} 个模型`);await upModels(id)}if(a==='quick-import')await quickImport();if(a==='new-model')modelForm();if(a==='edit-model')modelForm(state.models.find(x=>x.id===id));if(a==='delete-model'&&confirm('确定删除这个公开模型及所有路由？')){await api(`/api/admin/models/${id}`,'DELETE');await models()}if(a==='routes')await routeModal(id);if(a==='move-route')await moveRoute(Number(el.dataset.modelId),id,el.dataset.direction);if(a==='add-route')await routeForm(id);if(a==='import-routes')await routeImportForm(id);if(a==='edit-route'){let m=state.models.find(x=>x.id===Number(el.dataset.modelId));await routeForm(m.id,m.routes.find(x=>x.id===id))}if(a==='delete-route'&&confirm('确定删除该路由？')){await api(`/api/admin/routes/${id}`,'DELETE');await models();await routeModal(Number(el.dataset.modelId))}if(a==='edit-user')await editUser(id);if(a==='new-user')await userForm();if(a==='ban-user'){let u=state.users.find(x=>x.id===id);await api(`/api/admin/users/${id}`,'PUT',{banned:!u.banned});await users()}if(a==='delete-user'&&confirm('确定删除该用户？他的密钥也将失效。')){await api(`/api/admin/users/${id}`,'DELETE');await users()}if(a==='new-code')newCode();if(a==='delete-code'&&confirm('确定删除兑换码？')){await api(`/api/admin/codes/${id}`,'DELETE');await codes()}if(a==='log-detail')await logDetail(id);if(a==='new-announcement')announcementForm();if(a==='edit-announcement')announcementForm(state.announcements.find(x=>x.id===id));if(a==='delete-announcement'&&confirm('确定删除这条公告？')){await api(`/api/admin/announcements/${id}`,'DELETE');await announcements()}}catch(x){toast(x.message)}});
const replacedNodes=new WeakSet();let replaceScheduled=false;new MutationObserver(()=>{if(replaceScheduled)return;replaceScheduled=true;requestAnimationFrame(()=>{replaceScheduled=false;const overrides=state.public?.text_overrides||{};if(!Object.keys(overrides).length)return;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){if(replacedNodes.has(node)||node.parentElement?.closest('script,style,textarea,pre,.code'))continue;const raw=node.nodeValue,key=raw.trim();if(Object.prototype.hasOwnProperty.call(overrides,key)&&String(overrides[key])!==key){node.nodeValue=raw.replace(key,String(overrides[key]));replacedNodes.add(node)}}})}).observe(document.body,{subtree:true,childList:true,characterData:true});
function capabilityEditor(caps={},kind='language'){
  if(kind!=='language')return '';
  return `<div class="capabilities"><span class="small">语言模型能力（默认全选）</span><div class="checks">${LANGUAGE_CAPABILITY_OPTIONS.map(([key,label])=>`<label class="toggle"><input type="checkbox" data-cap="${key}" ${capabilityOn(caps,key)?'checked':''}> ${label}</label>`).join('')}</div></div>`;
}
function readCapabilities(form,old={},kind='language'){
  if(kind!=='language')return {};
  const caps={...old};form.querySelectorAll('[data-cap]').forEach(input=>caps[input.dataset.cap]=input.checked);return caps;
}
function customUpModel(id,existing){
  const channel=state.channels.find(x=>x.id==id),fixed=['image','tts','transcription'].includes(channel?.format)?channel.format:null;
  const kinds=fixed?[[fixed,kindName(fixed)]]:[['language','语言']];
  const caps=existing?.capabilities||{};
  modal(existing?'编辑上游模型':'自定义上游模型',`<form id="up-model-form">${field('上游模型 ID','model_id',existing?.model_id||'','text','required')}${select('类型','kind',kinds,existing?.kind||fixed||'language')}<div class="capability-slot">${capabilityEditor(caps,existing?.kind||fixed||'language')}</div><div class="actions"><button type="button" class="secondary" data-close>取消</button><button class="primary">保存</button></div></form>`);
  const form=$('#up-model-form');let draftCaps=caps;control(form,'kind').required=true;control(form,'kind').onchange=()=>{if(form.querySelector('[data-cap]'))draftCaps=readCapabilities(form,draftCaps);form.querySelector('.capability-slot').innerHTML=capabilityEditor(draftCaps,control(form,'kind').value)};
  form.onsubmit=async e=>{e.preventDefault();try{const kind=control(form,'kind').value;await api(`/api/admin/channels/${id}/models`,'POST',{model_id:control(form,'model_id').value,kind,capabilities:readCapabilities(form,draftCaps,kind)});toast('上游模型已保存');await upModels(id)}catch(x){toast(x.message)}};
}
function modelForm(m={}){
  modal(m.id?'编辑下游模型':'添加下游模型',`<form id="model-form"><div class="form-grid">${field('公开模型 ID','public_id',m.public_id||'','text','required')}${select('类型','kind',[['language','语言'],['tts','语音合成'],['transcription','语音识别'],['image','绘图']],m.kind||'language')}${select('计费方式','billing_mode',[['token','按量计费'],['request','按次计费']],m.billing_mode||'token')}<div data-price="input_price">${field('<span data-price-label>输入价格 / 百万 token</span>','input_price',m.input_price??0,'number','step="any" min="0"')}</div><div data-price="output_price">${field('<span data-price-label>输出价格 / 百万 token</span>','output_price',m.output_price??0,'number','step="any" min="0"')}</div><div data-price="cache_read_price">${field('缓存读取价格 / 百万 token','cache_read_price',m.cache_read_price??'','number','step="any" min="0" placeholder="留空则按输入价格"')}</div><div data-price="cache_write_price">${field('缓存写入价格 / 百万 token','cache_write_price',m.cache_write_price??'','number','step="any" min="0" placeholder="留空则按输入价格"')}</div><div data-price="unit_price">${field('每次调用价格','unit_price',m.unit_price??0,'number','step="any" min="0"')}</div><p class="small full price-hint"></p><div class="full capability-slot">${capabilityEditor(m.capabilities||{},m.kind||'language')}</div><label class="toggle"><input type="checkbox" name="enabled" ${m.enabled!==false&&m.enabled!==0?'checked':''}> 启用此模型</label></div><div class="actions"><button type="button" class="secondary" data-close>取消</button><button class="primary">保存</button></div></form>`);
  const form=$('#model-form');let draftCaps=m.capabilities||{};
  const syncPrices=()=>{const kind=control(form,'kind').value,mode=control(form,'billing_mode').value,show={input_price:mode==='token',output_price:mode==='token'&&kind!=='tts',cache_read_price:mode==='token'&&kind==='language',cache_write_price:mode==='token'&&kind==='language',unit_price:mode==='request'};for(const [k,on] of Object.entries(show))form.querySelector(`[data-price="${k}"]`).classList.toggle('hidden',!on);form.querySelector('[data-price="input_price"] [data-price-label]').textContent=kind==='tts'?'价格 / 百万字符':'输入价格 / 百万 token';form.querySelector('.price-hint').textContent=mode==='request'?'每次成功请求扣除固定费用，与 token 数量无关。':kind==='language'?'输入价格按未命中缓存的输入 token 计算；缓存读取/写入留空时按输入价格计费。价格全部为 0 即免费模型。':kind==='tts'?'语音合成按请求 input 文本的字符数计费。价格为 0 即免费模型。':'按上游返回的 usage token 计费；上游不返回 usage 的模型（如 DALL·E、Whisper）按量费用为 0，建议改用按次计费。'};
  control(form,'billing_mode').onchange=syncPrices;syncPrices();
  control(form,'kind').onchange=()=>{if(form.querySelector('[data-cap]'))draftCaps=readCapabilities(form,draftCaps);form.querySelector('.capability-slot').innerHTML=capabilityEditor(draftCaps,control(form,'kind').value);syncPrices()};
  form.onsubmit=async e=>{e.preventDefault();let d=formData(form);if(d.kind==='language')d.capabilities=readCapabilities(form,draftCaps);else if(!m.id||m.kind==='language')d.capabilities={};for(let k of ['input_price','output_price','unit_price'])d[k]=Number(d[k]||0);for(let k of ['cache_read_price','cache_write_price'])d[k]=d.kind==='language'&&d[k]!==''?Number(d[k]):null;d.enabled=control(form,'enabled').checked;try{await api('/api/admin/models'+(m.id?'/'+m.id:''),m.id?'PUT':'POST',d);closeModal();toast('模型已保存');await models()}catch(x){toast(x.message)}};
}
async function models(){
  state.models=await api('/api/admin/models');state.channels=await api('/api/admin/channels');
  $('#content').innerHTML=panel('下游模型目录','用户只能看到这里配置的公开模型 ID。每个模型可添加多个上游路由。',`<button class="secondary" data-action="quick-import">一键导入</button><button class="primary" data-action="new-model">＋ 添加模型</button>`,table(['公开模型 ID','类型','路由模式','价格','上游路由','操作'],state.models.map(m=>`<tr><td><span class="code">${esc(m.public_id)}</span>${m.enabled?'':badge('停用','orange')}</td><td>${badge(kindName(m.kind),'pink')}</td><td>${badge(m.mode==='balance'?'随机负载':'失败切换')}</td><td class="small">${esc(priceText(m))}</td><td><div class="route-list">${m.routes.map(r=>`<span class="route-chip">${esc(r.channel_name)} → ${esc(r.upstream_model_id)}</span>`).join('')||'<span class="small">暂无路由</span>'}</div></td><td><button class="text-btn" data-action="routes" data-id="${m.id}">路由</button><button class="text-btn" data-action="edit-model" data-id="${m.id}">编辑</button><button class="text-btn" data-action="delete-model" data-id="${m.id}">删除</button></td></tr>`)));
}
async function routeModal(id){
  let m=state.models.find(x=>x.id==id);if(!m){await models();m=state.models.find(x=>x.id==id)}
  const rows=m.routes.map((r,i)=>`<tr data-route-id="${r.id}"><td>${esc(r.channel_name)}</td><td class="code">${esc(r.upstream_model_id)}</td><td><div class="actions"><button class="text-btn" data-action="move-route" data-id="${r.id}" data-model-id="${id}" data-direction="up" ${i===0?'disabled':''} title="上移">↑</button><button class="text-btn" data-action="move-route" data-id="${r.id}" data-model-id="${id}" data-direction="down" ${i===m.routes.length-1?'disabled':''} title="下移">↓</button></div></td><td>${badge(r.enabled?'启用':'停用',r.enabled?'green':'orange')}</td><td><button class="text-btn" data-action="edit-route" data-id="${r.id}" data-model-id="${id}">编辑</button><button class="text-btn" data-action="delete-route" data-id="${r.id}" data-model-id="${id}">删除</button></td></tr>`);
  modal(`${m.public_id} · 路由`,`<div class="route-toolbar">${select('路由模式','route_mode',[['failover','失败切换'],['balance','随机负载均衡']],m.mode)}<div class="actions"><button class="secondary" data-action="import-routes" data-id="${id}">从渠道导入全部模型</button><button class="primary" data-action="add-route" data-id="${id}">＋ 添加路由</button></div></div>${table(['渠道','上游模型 ID','顺序','状态','操作'],rows)}<p class="hint">上移、下移会立即保存。失败切换按顺序尝试；随机负载从随机路由开始，失败后继续尝试其他路由。</p>`);
  $('#modal-body select[name="route_mode"]').onchange=async e=>{try{await api(`/api/admin/models/${id}`,'PUT',{mode:e.target.value});await models();await routeModal(id);toast('路由模式已保存')}catch(x){toast(x.message)}};
}
async function routeForm(modelId,r={}){
  state.channels=await api('/api/admin/channels');const model=state.models.find(x=>x.id==modelId),channels=state.channels.filter(c=>channelSupports(c,model.kind)||c.id==r.channel_id);
  if(!channels.length){modal('模型路由',`<p class="small">暂无支持 ${esc(kindName(model.kind))} 模型的上游渠道，请先添加匹配格式的渠道。</p>`);return}
  modal(r.id?'编辑路由':'添加模型路由',`<form id="route-form"><div class="muted-block">当前公开模型：<strong class="code">${esc(model.public_id)}</strong></div>${select('上游渠道','channel_id',channels.map(c=>[c.id,c.name+' · '+formatName(c.format)]),r.channel_id||channels[0].id)}<label>上游模型 ID<select name="upstream_model_id" required></select></label><label class="toggle"><input type="checkbox" name="custom_model"> 手动填写自定义上游模型 ID</label><div class="custom-model-field hidden">${field('自定义上游模型 ID','custom_model_id',r.upstream_model_id||'')}</div><label class="toggle"><input type="checkbox" name="enabled" ${r.enabled!==false&&r.enabled!==0?'checked':''}> 启用路由</label><div class="actions"><button type="button" class="secondary" data-close>取消</button><button class="primary">保存</button></div></form>`);
  const f=$('#route-form');async function loadOptions(){let data=await api(`/api/admin/channels/${control(f,'channel_id').value}/models`);data=data.filter(x=>x.kind===model.kind);const current=r.upstream_model_id||'',preferred=current||model.public_id;control(f,'upstream_model_id').innerHTML=data.map(x=>`<option value="${esc(x.model_id)}" ${x.model_id===preferred?'selected':''}>${esc(x.model_id)}</option>`).join('');control(f,'custom_model').checked=!!current&&!data.some(x=>x.model_id===current)||!data.length;toggleCustom();}
  function toggleCustom(){f.querySelector('.custom-model-field').classList.toggle('hidden',!control(f,'custom_model').checked);control(f,'custom_model_id').required=control(f,'custom_model').checked;control(f,'upstream_model_id').disabled=control(f,'custom_model').checked}
  control(f,'custom_model').onchange=toggleCustom;control(f,'channel_id').onchange=()=>loadOptions().catch(x=>toast(x.message));await loadOptions();
  f.onsubmit=async e=>{e.preventDefault();let d={channel_id:Number(control(f,'channel_id').value),upstream_model_id:control(f,'custom_model').checked?control(f,'custom_model_id').value.trim():control(f,'upstream_model_id').value,enabled:control(f,'enabled').checked};if(!d.upstream_model_id){toast('请选择或填写上游模型 ID');return}try{await api(r.id?`/api/admin/routes/${r.id}`:`/api/admin/models/${modelId}/routes`,r.id?'PUT':'POST',d);await models();await routeModal(modelId);toast('路由已保存')}catch(x){toast(x.message)}};
}
async function routeImportForm(modelId){
  state.channels=await api('/api/admin/channels');const model=state.models.find(x=>x.id==modelId),channels=state.channels.filter(c=>channelSupports(c,model.kind));
  if(!channels.length){modal('导入路由',`<p class="small">暂无支持 ${esc(kindName(model.kind))} 模型的上游渠道，请先添加匹配格式的渠道。</p>`);return}
  modal('从渠道导入全部模型',`<form id="route-import-form"><div class="muted-block">当前公开模型：<strong class="code">${esc(model.public_id)}</strong></div><p class="small">把所选渠道模型列表中所有同类型的上游模型，都添加为该公开模型的路由，排在现有路由之后；已存在的路由会跳过。请先在渠道的“模型”里拉取列表。</p>${select('上游渠道','channel_id',channels.map(c=>[c.id,c.name+' · '+formatName(c.format)]),channels[0].id)}<div class="actions"><button type="button" class="secondary" data-close>取消</button><button class="primary">全部导入</button></div></form>`);
  $('#route-import-form').onsubmit=async e=>{e.preventDefault();try{let d=await api(`/api/admin/models/${modelId}/routes/import`,'POST',{channel_id:Number(control(e.target,'channel_id').value)});await models();await routeModal(modelId);toast(d.count?`已添加 ${d.count} 条路由`:'没有可添加的新路由')}catch(x){toast(x.message)}};
}
async function moveRoute(modelId,routeId,direction){
  const model=state.models.find(x=>x.id===modelId),ids=model.routes.map(x=>x.id),i=ids.indexOf(routeId),other=i+(direction==='up'?-1:1);if(i<0||other<0||other>=ids.length)return;
  [ids[i],ids[other]]=[ids[other],ids[i]];
  const tbody=$('#modal-body tbody'),buttons=[...tbody.querySelectorAll('[data-action="move-route"]')],disabled=buttons.map(button=>button.disabled);buttons.forEach(button=>button.disabled=true);
  try{await api(`/api/admin/models/${modelId}/routes/reorder`,'PUT',{route_ids:ids})}catch(error){buttons.forEach((button,index)=>button.disabled=disabled[index]);throw error}
  model.routes=ids.map(id=>model.routes.find(route=>route.id===id));
  const rows=[...tbody.querySelectorAll('[data-route-id]')],positions=new Map(rows.map(row=>[Number(row.dataset.routeId),row.getBoundingClientRect().top])),byId=new Map(rows.map(row=>[Number(row.dataset.routeId),row]));
  ids.forEach(id=>tbody.appendChild(byId.get(id)));
  ids.forEach((id,index)=>{const row=byId.get(id),distance=positions.get(id)-row.getBoundingClientRect().top;if(distance&&!matchMedia('(prefers-reduced-motion: reduce)').matches)row.querySelectorAll('td').forEach(cell=>cell.animate?.([{transform:`translateY(${distance}px)`},{transform:'translateY(0)'}],{duration:320,easing:'ease-out'}));row.querySelector('[data-direction="up"]').disabled=index===0;row.querySelector('[data-direction="down"]').disabled=index===ids.length-1});
  const modelRow=document.querySelector(`#content [data-action="routes"][data-id="${modelId}"]`)?.closest('tr');if(modelRow)modelRow.querySelector('.route-list').innerHTML=model.routes.map(route=>`<span class="route-chip">${esc(route.channel_name)} → ${esc(route.upstream_model_id)}</span>`).join('');
}
function modelChoices(models,selected=[]){return models.length?`<div class="model-choices"><div class="model-choice-tools"><button type="button" class="text-btn" data-choose-models="all">全选</button><button type="button" class="text-btn" data-choose-models="none">清空</button><span class="small model-choice-count"></span></div><div class="model-choice-list">${models.map(m=>`<label class="toggle"><input type="checkbox" name="allowed_models" value="${esc(m.public_id)}" ${selected.includes(m.public_id)?'checked':''}> <span class="code">${esc(m.public_id)}</span></label>`).join('')}</div></div>`:'<p class="small">暂无模型。</p>'}
function selectedModels(form){return [...form.querySelectorAll('input[name="allowed_models"]:checked')].map(x=>x.value)}
function allModelsToggle(form,checkboxName='all_models'){const box=form.elements.namedItem(checkboxName),boxes=[...form.querySelectorAll('input[name="allowed_models"]')],count=form.querySelector('.model-choice-count');const sync=()=>{const off=!!box?.checked;boxes.forEach(x=>x.disabled=off);form.querySelectorAll('[data-choose-models]').forEach(b=>b.disabled=off);form.querySelector('.model-choices')?.classList.toggle('disabled',off);if(count)count.textContent=`已选 ${boxes.filter(x=>x.checked).length} / ${boxes.length}`};form.querySelectorAll('[data-choose-models]').forEach(b=>b.onclick=()=>{boxes.forEach(x=>x.checked=b.dataset.chooseModels==='all');sync()});boxes.forEach(x=>x.onchange=sync);if(box)box.onchange=sync;sync()}
async function users(){
  state.users=await api('/api/admin/users');$('#content').innerHTML=panel('用户管理','为账户配置模型权限、余额及状态。',`<button class="primary" data-action="new-user">＋ 新建用户</button>`,table(['用户','身份 / 状态','余额','可用模型','加入时间','操作'],state.users.map(u=>`<tr><td><strong>${esc(u.username)}</strong></td><td>${badge(u.is_admin?'管理员':'用户',u.is_admin?'pink':'green')} ${u.banned?badge('已封禁','red'):''}</td><td>${u.unlimited_balance?'∞':money(u.balance)}</td><td class="small">${u.all_models?'全部':esc(u.allowed_models.join('、')||'无')}</td><td>${date(u.created_at)}</td><td><button class="text-btn" data-action="edit-user" data-id="${u.id}">编辑</button>${u.is_admin?'':`<button class="text-btn" data-action="ban-user" data-id="${u.id}">${u.banned?'解封':'封禁'}</button><button class="text-btn" data-action="delete-user" data-id="${u.id}">删除</button>`}</td></tr>`)));
}
async function editUser(id){return userForm(state.users.find(x=>x.id===id))}
async function userForm(u={}){
  const models=await api('/api/admin/models'),admin=!!u.is_admin,all=admin||!!u.all_models,unlimited=admin||!!u.unlimited_balance;
  modal(u.id?`编辑用户 · ${u.username}`:'新建用户',`<form id="user-form"><div class="form-grid">${u.id?'':field('用户名','username','','text','required pattern="[A-Za-z0-9_]{3,32}"')}${field('余额','balance',u.balance??0,'number',`step="0.000001" ${unlimited?'disabled':''}`)}<label class="toggle"><input type="checkbox" name="unlimited_balance" ${unlimited?'checked':''} ${admin?'disabled':''}> 无限余额</label><label class="toggle"><input type="checkbox" name="all_models" ${all?'checked':''} ${admin?'disabled':''}> 全部模型</label><div class="full"><span class="field-label">可用模型（可多选）</span>${modelChoices(models,u.allowed_models||[])}<p class="small">勾选“全部模型”时，此列表不需要选择；取消勾选后可逐项授权。</p></div>${field(u.id?'重设密码（留空不修改）':'初始密码','password','','password',u.id?'autocomplete="new-password"':'required autocomplete="new-password"')}<label class="toggle"><input type="checkbox" name="banned" ${u.banned?'checked':''} ${admin?'disabled':''}> 封禁账户</label></div><div class="actions"><button type="button" class="secondary" data-close>取消</button><button class="primary">保存</button></div></form>`);
  const f=$('#user-form');allModelsToggle(f);control(f,'unlimited_balance').onchange=()=>{control(f,'balance').disabled=control(f,'unlimited_balance').checked};
  f.onsubmit=async e=>{e.preventDefault();const d={balance:Number(control(f,'balance').value||0),all_models:admin||control(f,'all_models').checked,unlimited_balance:admin||control(f,'unlimited_balance').checked,allowed_models:admin||control(f,'all_models').checked?[]:selectedModels(f),banned:!admin&&control(f,'banned').checked};if(!u.id)d.username=control(f,'username').value;if(control(f,'password').value)d.password=control(f,'password').value;try{await api(u.id?`/api/admin/users/${u.id}`:'/api/admin/users',u.id?'PUT':'POST',d);closeModal();toast('用户已保存');await users()}catch(x){toast(x.message)}};
}
async function codes(){
  const data=await api('/api/admin/codes');$('#content').innerHTML=panel('兑换码','完整兑换码可随时查看和复制。',`<button class="primary" data-action="new-code">＋ 生成兑换码</button>`,table(['兑换码','金额','使用情况','过期时间','操作'],data.map(c=>`<tr><td><span class="code secret-code">${esc(c.code||c.prefix+'…')}</span></td><td>${money(c.amount)} ${esc(state.public.currency_name)}</td><td>${c.uses} / ${c.max_uses}</td><td>${date(c.expires_at)}</td><td>${c.code?`<button class="text-btn" data-copy="${esc(c.code)}">复制</button>`:''}<button class="text-btn" data-action="delete-code" data-id="${c.id}">删除</button></td></tr>`)));
}
function newCode(){modal('生成兑换码',`<form id="code-form"><div class="form-grid">${field('每码金额','amount',100,'number','required min="0.000001" step="0.000001"')}${field('生成数量','count',1,'number','min="1" max="100"')}${field('每码可使用次数','max_uses',1,'number','min="1"')}${field('过期日期（可不填）','expires_at','','date')}</div><div class="actions"><button type="button" class="secondary" data-close>取消</button><button class="primary">生成</button></div></form>`);$('#code-form').onsubmit=async e=>{e.preventDefault();let d=formData(e.target);d.amount=Number(d.amount);d.count=Number(d.count);d.max_uses=Number(d.max_uses);d.expires_at=d.expires_at?Math.floor(new Date(d.expires_at+'T23:59:59').getTime()/1000):null;try{let r=await api('/api/admin/codes','POST',d);await codes();modal('兑换码已生成',`<p class="small">可在兑换码页面再次查看并复制。</p><pre class="json-view">${esc(r.codes.join('\n'))}</pre><div class="actions" style="margin-top:14px"><button class="primary" data-copy="${esc(r.codes.join('\n'))}">复制全部</button><button class="secondary" data-close>完成</button></div>`)}catch(x){toast(x.message)}}}
async function keys(){
  state.keys=await api('/api/me/keys');$('#content').innerHTML=panel('我的 API Keys','完整密钥仅向当前账户显示，可随时复制或修改模型权限。',`<button class="primary" data-action="new-key">＋ 新建密钥</button>`,table(['名称','完整密钥','模型范围','最近使用','操作'],state.keys.map(k=>`<tr><td>${esc(k.name)}</td><td><span class="code secret-code">${esc(k.key||k.prefix+'…')}</span></td><td>${k.allowed_models.length?esc(k.allowed_models.join('、')):'我可用的全部模型'}</td><td>${date(k.last_used_at)}</td><td>${k.key?`<button class="text-btn" data-copy="${esc(k.key)}">复制</button>`:''}<button class="text-btn" data-action="edit-key" data-id="${k.id}">编辑</button><button class="text-btn" data-action="delete-key" data-id="${k.id}">删除</button></td></tr>`)));
}
async function keyForm(k={}){
  const models=await api('/api/me/models');modal(k.id?'编辑 API Key':'创建 API Key',`<form id="key-form">${field('密钥名称','name',k.name||'新密钥','text','required')}<label class="toggle"><input type="checkbox" name="all_models" ${!k.allowed_models?.length?'checked':''}> 我可用的全部模型</label><span class="field-label">允许模型（可多选）</span>${modelChoices(models,k.allowed_models||[])}<div class="actions"><button type="button" class="secondary" data-close>取消</button><button class="primary">${k.id?'保存':'创建'}</button></div></form>`);
  const f=$('#key-form');allModelsToggle(f);f.onsubmit=async e=>{e.preventDefault();const d={name:control(f,'name').value,allowed_models:control(f,'all_models').checked?[]:selectedModels(f)};try{const result=await api(k.id?`/api/me/keys/${k.id}`:'/api/me/keys',k.id?'PUT':'POST',d);await keys();if(k.id){closeModal();toast('密钥已更新')}else modal('密钥已创建',`<p class="small">完整密钥也可在“我的密钥”页面再次查看。</p><div class="muted-block code">${esc(result.key)}</div><div class="actions" style="margin-top:15px"><button class="primary" data-copy="${esc(result.key)}">复制密钥</button><button class="secondary" data-close>完成</button></div>`)}catch(x){toast(x.message)}};
}
async function newKey(){await keyForm()}
function announcementCard(a){return `<article class="announcement-card"><div class="announcement-meta">${date(a.created_at)}${a.published===0?' · 草稿':''}</div><h4>${esc(a.title)}</h4>${a.image_url?`<img src="${esc(a.image_url)}" alt="${esc(a.title)}" loading="lazy">`:''}<div class="announcement-body">${esc(a.body)}</div>${state.user.is_admin?`<div class="actions"><button class="text-btn" data-action="edit-announcement" data-id="${a.id}">编辑</button><button class="text-btn" data-action="delete-announcement" data-id="${a.id}">删除</button></div>`:''}</article>`}
async function announcements(){state.announcements=await api(state.user.is_admin?'/api/admin/announcements':'/api/announcements');$('#content').innerHTML=panel('公告',state.user.is_admin?'在这里发布、编辑或删除图文公告；草稿只有管理员可见。':'站点发布的最新消息。',state.user.is_admin?'<button class="primary" data-action="new-announcement">＋ 添加公告</button>':'',state.announcements.length?`<div class="announcement-list">${state.announcements.map(announcementCard).join('')}</div>`:empty('暂无公告。'))}
function announcementForm(a={}){modal(a.id?'编辑公告':'添加公告',`<form id="announcement-form">${field('标题','title',a.title||'','text','required maxlength="120"')}${textarea('正文','body',a.body||'',8)}<p class="small">正文按原有换行显示。图片可选，支持 PNG、JPG、WebP、GIF，最多 5 MB。</p>${assetField('公告图片','image_url',a.image_url||'')}<label class="toggle"><input type="checkbox" name="published" ${a.published!==0?'checked':''}> 立即发布</label><div class="actions"><button type="button" class="secondary" data-close>取消</button><button class="primary">保存公告</button></div></form>`,true);const form=$('#announcement-form');const input=form.querySelector('[data-upload]');input.onchange=async()=>{let file=input.files[0];if(!file)return;let fd=new FormData();fd.append('file',file);try{let r=await fetch('/api/admin/assets',{method:'POST',body:fd,credentials:'same-origin'});let d=await r.json();if(!r.ok)throw new Error(d.detail||'上传失败');control(form,'image_url').value=d.url;form.querySelector('.asset-preview').innerHTML=`<img class="asset-thumb" src="${esc(d.url)}" alt="公告图片">`;toast('图片已上传，保存公告后生效')}catch(e){input.value='';toast(e.message)}};form.querySelector('[data-clear-asset]').onclick=()=>{control(form,'image_url').value='';input.value='';form.querySelector('.asset-preview').innerHTML='<span class="small">尚未上传</span>'};form.onsubmit=async e=>{e.preventDefault();let d={title:control(form,'title').value,body:control(form,'body').value,image_url:control(form,'image_url').value,published:control(form,'published').checked};try{await api(a.id?`/api/admin/announcements/${a.id}`:'/api/admin/announcements',a.id?'PUT':'POST',d);closeModal();toast('公告已保存');await announcements()}catch(x){toast(x.message)}}}
async function logs(){
  const base=state.user.is_admin?'/api/admin/logs':'/api/me/logs';state.logs=await api(base+'?limit=50');$('#content').innerHTML=panel('请求日志',state.user.is_admin?'显示所有用户的请求。完整内容按需打开。':'这里只显示你自己的请求。完整内容按需打开。',`<button class="secondary" data-view="logs">刷新</button>`,table(['时间','用户 / 模型','接口','尝试路径 / 最终渠道','结果','耗时','用量','费用','操作'],state.logs.map(l=>`<tr><td class="small">${date(l.created_at)}</td><td>${esc(l.username||'未知')}<br><span class="code">${esc(l.model_id)}</span></td><td class="small">${esc(l.endpoint)}</td><td class="small">${routeTraceHtml(l.route_trace,l.selected_channel_name,false,l.route_id)}</td><td>${badge(l.status,l.status===200?'green':'red')}</td><td>${l.duration_ms} ms</td><td class="small">${usageText(l)}</td><td>${money(l.cost)}</td><td><button class="text-btn" data-action="log-detail" data-id="${l.id}">详情</button></td></tr>`)));
}
function routeTraceHtml(trace,selected,showErrors=false,routeId=null){const upModel=a=>a&&a.upstream_model?` · ${esc(a.upstream_model)}`:'';let attempts=(trace||[]).map(a=>`<div>${a.number?`${a.number}. `:''}${esc(a.channel_name||`路由 #${a.route_id}`)}${upModel(a)} → ${esc(a.result==='succeeded'?'成功':a.result==='interrupted'?'流中断':a.result==='skipped'?'跳过':a.status===200?'HTTP 200 内容错误':a.status?`HTTP ${a.status}`:a.error?'连接或处理失败':'失败')}${showErrors&&a.error?`<div class="attempt-error">${esc(String(a.error).slice(0,300))}</div>`:''}</div>`).join('');return `${attempts||'<span class="small">旧日志无尝试明细</span>'}<strong class="selected-channel">最终：${esc(selected||'无可用渠道')}${selected?upModel([...(trace||[])].reverse().find(a=>a.route_id===routeId&&a.result!=='skipped')):''}</strong>`}
async function logDetail(id){const base=state.user.is_admin?'/api/admin/logs':'/api/me/logs';modal('加载日志…','<div class="empty">正在读取预览</div>');try{let d=await api(`${base}/${id}`);modal(`请求日志 #${id}`,`<p class="small">${date(d.created_at)} · ${esc(d.model_id)} · ${d.duration_ms} ms · ${d.attempt_count} 次尝试</p><div class="route-trace">${routeTraceHtml(d.route_trace,d.selected_channel_name,true,d.route_id)}</div><pre class="json-view log-preview">${esc(JSON.stringify(d,null,2))}</pre><div class="actions" style="margin-top:14px"><a class="secondary" href="${base}/${id}?download=true" download="request-${id}.json">下载完整 JSON</a></div>`,true)}catch(x){toast(x.message);closeModal()}}

boot();
